# PowerShell查看所有运行中的服务
Get-WmiObject Win32_Service | Where-Object { $_.State -eq 'Running' } | Select-Object Name, ProcessId, PathName, StartMode, State, StartName | Format-Table -AutoSize

# 启动/停止服务
